from collections import deque,defaultdict
H,W=len(grid),len(grid[0])
seen=set(); comps=[]
for r in range(H):
 for c in range(W):
  if grid[r][c]!=3 and (r,c) not in seen:
   col=grid[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    p=q.pop();cells.append(p)
    for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
     x,y=p[0]+dr,p[1]+dc
     if 0<=x<H and 0<=y<W and grid[x][y]==col and (x,y) not in seen:
      seen.add((x,y));q.append((x,y))
   comps.append((col,cells))
def norm(cells):
 a=min(x for x,y in cells);b=min(y for x,y in cells)
 return tuple(sorted((x-a,y-b) for x,y in cells))
for i,(col,cells) in enumerate(comps):
 print(i,col,len(cells),(min(x for x,y in cells),max(x for x,y in cells),min(y for x,y in cells),max(y for x,y in cells)),norm(cells))
